#!/bin/bash
# Verify the latest Alembic migration has a real downgrade() body.
#
# SPEC.md §17.3 mandates every migration ship both upgrade() and downgrade().
# This guard catches the common foot-gun: an autogenerated revision where
# downgrade() got left as `pass` and only the upgrade() side was filled in.
#
# Usage:
#   bash scripts/check_migration.sh
#   bash scripts/check_migration.sh path/to/specific_migration.py
#
# Exit codes:
#   0  — downgrade has an effective body
#   1  — downgrade is empty / only `pass` / only a docstring
#   2  — file unparseable or downgrade() not found

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
VERSIONS="${PROJECT_ROOT}/backend/alembic/versions"

TARGET="${1:-}"
if [ -z "${TARGET}" ]; then
    # Alembic revision filenames are NN_*.py — lexical sort puts the newest last.
    TARGET="$(ls -1 "${VERSIONS}"/*.py 2>/dev/null | sort | tail -n 1)"
fi

if [ -z "${TARGET}" ] || [ ! -f "${TARGET}" ]; then
    echo "FAIL: no migration file found (checked: ${VERSIONS})"
    exit 2
fi

# Walk the file, find the downgrade() function, and count "effective" lines:
# anything that isn't blank, a pure `pass`, a comment, or part of a docstring.
EFFECTIVE="$(awk '
    BEGIN { in_fn = 0; in_docstring = 0; quote = ""; n = 0 }

    /^def downgrade[[:space:]]*\(/ { in_fn = 1; next }
    in_fn && /^def [A-Za-z_]/      { exit }
    !in_fn                          { next }

    {
        line = $0
        sub(/^[[:space:]]+/, "", line)

        # Inside a multi-line docstring? Wait for the closing fence.
        if (in_docstring) {
            if (index(line, quote) > 0) { in_docstring = 0 }
            next
        }

        # Opening docstring """…""" or '\''\'''\''…'\''\'''\''
        if (line ~ /^"""/ || line ~ /^'\''\'''\''/) {
            quote = substr(line, 1, 3)
            rest  = substr(line, 4)
            # Single-line docstring closes on the same line.
            if (index(rest, quote) == 0) { in_docstring = 1 }
            next
        }

        if (line == "")           next
        if (line == "pass")       next
        if (substr(line, 1, 1) == "#") next

        n++
    }
    END { print n }
' "${TARGET}")"

if [ "${EFFECTIVE}" -ge 1 ] 2>/dev/null; then
    echo "OK: ${TARGET##*/} has a non-empty downgrade() (${EFFECTIVE} effective lines)"
    exit 0
fi

echo "FAIL: ${TARGET##*/} — downgrade() is empty or only contains 'pass'."
echo "SPEC.md §17.3: every migration must implement a real reverse operation."
exit 1
